"use client";
import {AnimatePresence,motion} from 'framer-motion';import {useEffect,useMemo,useState} from 'react';import {Activity,ArrowLeft,Bell,BookOpen,CalendarDays,CheckCircle2,ChevronRight,Clock3,Edit3,Filter,Home,KeyRound,ListChecks,Menu,Plus,Search,Settings,Shield,Star,Target,UserCircle,Users, X} from 'lucide-react';
import type {AfkRecord,AdminCheck,AuditLog,NavCategory,Notification,Task,TaskStatus,User,RoleCode} from '@/lib/types';
import AdminList, {AdminAutomation} from '@/components/admin-list';import {ROLE_NAMES,starName,defaultPrefix} from '@/lib/permissions';

const PERMISSION_NAMES:Record<string,string>={VIEW_CONTENT:'Просмотр содержимого',EDIT_CONTENT:'Редактирование содержимого',MANAGE_NAVIGATION:'Управление навигацией',MANAGE_PREFIXES:'Управление префиксами',MANAGE_USERS:'Управление пользователями',MANAGE_TASKS:'Управление заданиями',MANAGE_AFK:'Управление AFK',VIEW_STATISTICS:'Просмотр статистики',MANAGE_STATISTICS:'Управление статистикой',VIEW_AUDIT_LOG:'Просмотр журнала действий'};
const PRIORITY_NAMES:Record<string,string>={LOW:'Низкий',MEDIUM:'Средний',HIGH:'Высокий'};

type AdminRow={id:string;group:'BLACK'|'BLUE';rank:string;stars:number;source:string;sourceChat?:string;sourceSeenAt?:string;rankTitle:string;groupTitle:string;user:User};type Data={me:User;users:User[];admins:AdminRow[];nav:NavCategory[];tasks:Task[];afk:AfkRecord[];notifications:Notification[];audit:AuditLog[];permissions:string[];rolePermissions:Record<string,string[]>;stats:{checks:number;avg:number;messages:number};checks:AdminCheck[]};
const cls=(...a:string[])=>a.filter(Boolean).join(' ');
function tg(){return (globalThis as any).Telegram?.WebApp}
async function api(url:string,opt?:RequestInit){const r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt?.headers||{})}});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`);return j}
function Stars({n,size=16}:{n:number;size?:number}){return <span className="inline-flex gap-0.5 text-amber-300" title={starName(n)} aria-label={starName(n)}>{Array.from({length:5},(_,i)=><Star key={i} size={size} fill={i<n?'currentColor':'transparent'} strokeWidth={i<n?2.5:1.5}/>)}</span>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <AnimatePresence mode="wait"><motion.div key="modal" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 p-3 backdrop-blur-sm" onMouseDown={onClose}><motion.div initial={{y:35,scale:.98}} animate={{y:0,scale:1}} exit={{y:25,scale:.98}} onMouseDown={e=>e.stopPropagation()} className="glass w-full max-w-lg rounded-3xl p-5 max-h-[86vh] overflow-y-auto scrollbar"><div className="flex items-center justify-between mb-4"><h2 className="text-lg font-bold">{title}</h2><button className="rounded-full bg-white/5 p-2" onClick={onClose}><X size={18}/></button></div>{children}</motion.div></motion.div></AnimatePresence>}
function Button({children,onClick,variant='default',disabled=false}:{children:React.ReactNode;onClick?:()=>void;variant?:'default'|'primary'|'danger';disabled?:boolean}){return <button disabled={disabled} onClick={onClick} className={cls('tap rounded-2xl px-4 py-3 font-semibold text-sm border',variant==='primary'?'bg-violet-500/20 border-violet-300/25':'',variant==='danger'?'bg-red-500/10 border-red-400/20 text-red-200':'','border-white/10 bg-white/[.045] disabled:opacity-40')}>{children}</button>}
export default function Dashboard(){const [data,setData]=useState<Data|null>(null);const [tab,setTab]=useState('home');const [previousTab,setPreviousTab]=useState('home');const [compact,setCompact]=useState(false);const [modal,setModal]=useState<{kind:string;id?:string}|null>(null);const [toast,setToast]=useState('');const [loading,setLoading]=useState(true);useEffect(()=>{const t=tg();t?.ready?.();t?.expand?.();t?.setHeaderColor?.('#050711');t?.enableClosingConfirmation?.()},[]);useEffect(()=>{const t=tg();const back=t?.BackButton;if(!back)return;const onBack=()=>{if(tab==='admin-list'||tab==='admin-automation'){setTab('admin');return}if(tab==='admin'){setTab('home');return}if(tab!=='home'){setTab('home');return}};if(tab==='home')back.hide?.();else{back.show?.();back.onClick?.(onBack)}return()=>back.offClick?.(onBack)},[tab,previousTab]);useEffect(()=>{let timer:number|undefined;const syncTelegramProfile=async()=>{const t=tg();const init=t?.initData;if(init){try{await api('/api/auth/telegram',{method:'POST',body:JSON.stringify({initData:init})})}catch{} }await load()};syncTelegramProfile();const onVisible=()=>{if(document.visibilityState==='visible')syncTelegramProfile()};document.addEventListener('visibilitychange',onVisible);timer=window.setInterval(syncTelegramProfile,60000);return()=>{document.removeEventListener('visibilitychange',onVisible);if(timer)window.clearInterval(timer)}},[]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),2200);return()=>clearTimeout(t)}},[toast]);useEffect(()=>{try{const x=JSON.parse(localStorage.getItem('tc_settings')||'{}');if(typeof x.compact==='boolean')setCompact(x.compact)}catch{}},[]);
async function load(){setLoading(true);try{const d=await api('/api/state');setData(d)}catch(e){setToast((e as Error).message)}finally{setLoading(false)}}
function navTo(t:string){tg()?.HapticFeedback?.impactOccurred?.('light');setTab(t)}
function openAdminList(){setTab('admin-list')} function openAdminAutomation(){setTab('admin-automation')}
if(loading)return <div className="app-bg min-h-screen grid place-items-center"><div className="glass rounded-3xl p-6 animate-pulse">Загрузка…</div></div>;
if(!data)return <div className="app-bg min-h-screen grid place-items-center p-5"><div className="glass w-full max-w-md rounded-3xl p-6 text-center"><div className="mx-auto mb-4 grid h-14 w-14 place-items-center rounded-2xl bg-violet-400/10 text-2xl">✈️</div><h1 className="text-xl font-black">Откройте приложение в Telegram</h1><p className="mt-2 text-sm leading-6 text-white/50">Авторизация выполняется автоматически через Telegram. Откройте Mini App из кнопки бота — имя, username и Telegram ID будут получены с сервера после проверки initData.</p><div className="mt-4 rounded-2xl border border-white/10 bg-white/[.03] p-3 text-left text-xs text-white/45">Для локального тестирования включите DEMO_MODE только в .env.local.</div></div></div>;
const canAdmin=data.permissions.some(p=>['MANAGE_TASKS','MANAGE_NAVIGATION','MANAGE_AFK','VIEW_AUDIT_LOG','MANAGE_USERS'].includes(p));const nav=data.nav;return <main className={cls('app-bg min-h-screen',compact?'compact-mode':'')}><div className="mx-auto w-full max-w-lg safe px-4 pt-6 sm:px-6">{tab==='home'&&<HomeView data={data} onOpen={k=>setModal({kind:k})} navTo={navTo}/>} {tab==='stats'&&<StatsView data={data}/>} {tab==='tasks'&&<TasksView data={data} refresh={load} toast={setToast} onOpen={id=>setModal({kind:'task',id})}/>} {tab==='nav'&&<NavView nav={nav} onOpen={id=>setModal({kind:'nav',id})}/>} {tab==='afk'&&<AfkView data={data} refresh={load} toast={setToast}/>} {tab==='notifications'&&<NotificationsView data={data} refresh={load}/>} {tab==='profile'&&<ProfileView data={data} refresh={load} toast={setToast} onAdmin={()=>navTo('admin')} compact={compact} setCompact={setCompact}/>} {tab==='admin'&&canAdmin&&<AdminView data={data} refresh={load} toast={setToast} onOpen={k=>setModal({kind:k})} navTo={navTo} openAdminList={openAdminList} openAdminAutomation={openAdminAutomation}/>} {tab==='admin-list'&&<><PageTitle title="Список админов" back={()=>navTo('admin')}/><AdminList canSync={data.me.stars>=5} canCheck={data.me.stars>=4} onToast={setToast}/></>} {tab==='admin-automation'&&<><PageTitle title="Автоматизация админов" back={()=>navTo('admin')}/><AdminAutomation canSync={data.me.stars>=5} onToast={setToast}/></>} {tab==='admin'&&!canAdmin&&<Empty title="Доступ запрещён" text="Для административной панели нужна роль с соответствующим permission."/>}</div><Bottom active={tab} onChange={navTo} admin={canAdmin}/>{modal?.kind==='task'&&<TaskModal task={data.tasks.find(t=>t.id===modal.id)} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='nav'&&<NavModal item={findNav(data.nav,modal.id!)} onClose={()=>setModal(null)}/>} {modal?.kind==='user'&&<UserModal data={data} userId={modal.id||data.users[0].id} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='role'&&<RoleModal data={data} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='audit'&&<AuditModal logs={data.audit} onClose={()=>setModal(null)}/>} {modal?.kind==='stats'&&<StatsModal data={data} onClose={()=>setModal(null)}/>} {modal?.kind==='nav-admin'&&<AdminNavModal data={data} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='admin-afk'&&<AdminAfkModal data={data} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='prefix'&&<PrefixModal data={data} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {modal?.kind==='admin-tasks'&&<AdminTasksModal data={data} onClose={()=>setModal(null)} refresh={load} toast={setToast}/>} {toast&&<div className="fixed bottom-24 left-1/2 z-[60] -translate-x-1/2 rounded-full border border-white/10 bg-black/80 px-4 py-2 text-sm shadow-2xl">{toast}</div>}</main>}
function HomeView({data,onOpen,navTo}:{data:Data;onOpen:(k:string)=>void;navTo:(t:string)=>void}){const cards=[['Навигация','Разделы и материалы','nav',BookOpen],['Итоги проверки',`${data.stats.checks} проверок · ${data.stats.avg}%`,'stats',CheckCircle2],['Задания',`${data.tasks.filter(t=>t.status!=='DONE').length} активных`,'tasks',Target],['AFK',data.afk.filter(a=>a.active).length?'Есть активные':'Статус отсутствия','afk',Clock3],['Мой профиль','Статистика аккаунта','profile',UserCircle]] as const;return <><Header data={data}/><div className="mt-5 space-y-3">{cards.map(([a,b,k,I])=><button key={k} onClick={()=>navTo(k)} className="glass tap w-full rounded-3xl p-4 text-left flex items-center gap-4"><div className="rounded-2xl bg-violet-400/10 p-3 text-violet-200"><I size={22}/></div><div className="flex-1"><div className="font-bold">{a}</div><div className="text-sm text-white/45 mt-1">{b}</div></div><ChevronRight size={18} className="text-white/35"/></button>)}</div><div className="mt-7 mb-3 flex items-center justify-between"><h3 className="font-bold">Навигация</h3><button onClick={()=>navTo('nav')}><ChevronRight size={18}/></button></div><div className="glass overflow-hidden rounded-3xl">{data.nav.map(c=><button key={c.id} onClick={()=>navTo('nav')} className="tap flex w-full items-center gap-3 border-b border-white/10 px-4 py-4 text-left last:border-0"><span className="text-violet-200">{c.icon}</span><span className="flex-1 font-medium">{c.title}</span><ChevronRight size={16} className="text-white/30"/></button>)}</div></>}
function Header({data}:{data:Data}){return <header><div className="text-sm text-white/45">Добро пожаловать</div><div className="mt-1 text-2xl font-black">@{data.me.username}</div><div className="mt-2 flex items-center gap-3"><Stars n={data.me.stars}/>{(()=>{const dp=defaultPrefix(data.me.stars);return <span className="status-chip status-chip-glow" style={{'--chip-color':data.me.prefixColor||dp.color} as React.CSSProperties}>{data.me.prefix||dp.prefix}</span>})()}</div></header>}
function Bottom({active,onChange,admin}:{active:string;onChange:(s:string)=>void;admin:boolean}){const items=[['home','Главная',Home],['nav','Навигация',BookOpen],['tasks','Задания',Target],['afk','AFK',Clock3],['admin-list','Админы',Users],['notifications','Колокол',Bell],['profile','Профиль',UserCircle],...(admin?[['admin','Админ',Shield]]:[])];return <div className="nav-bottom fixed bottom-0 left-0 right-0 z-40 border-t border-white/10 bg-[#080a14]/90 backdrop-blur-xl"><div className="mx-auto flex max-w-xl overflow-x-auto px-1 py-2 scrollbar">{items.map(([k,l,I])=><button key={k as string} onClick={()=>onChange(k as string)} className={cls('tap min-w-[62px] flex-1 rounded-2xl px-2 py-2 text-[10px] font-medium',active===k?'bg-violet-400/10 text-white':'text-white/45')}><div className="flex justify-center"><I size={18}/></div><div className="mt-1 whitespace-nowrap">{l as string}</div></button>)}</div></div>}
function PageTitle({title,back}:{title:string;back?:()=>void}){return <div className="mb-5 flex items-center gap-3">{back&&<button onClick={back} className="glass tap rounded-2xl p-2.5"><ArrowLeft size={19}/></button>}<div><h1 className="text-xl font-black">{title}</h1><p className="text-sm text-white/40">Управление системой</p></div></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="glass rounded-3xl p-8 text-center"><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-white/5"><Search size={20}/></div><div className="font-bold">{title}</div><div className="mt-1 text-sm text-white/40">{text}</div></div>}
function NavView({nav,onOpen}:{nav:NavCategory[];onOpen:(id:string)=>void}){return <><PageTitle title="Навигация"/><div className="space-y-4">{nav.map(c=><section key={c.id} className="nav-card glass overflow-hidden rounded-3xl"><div className="nav-card-head"><span className="nav-card-icon">{c.icon}</span><div className="min-w-0 flex-1"><div className="font-bold">{c.title}</div><div className="mt-0.5 text-xs text-white/35">{c.items.length} {c.items.length===1?'тема':'тем'}</div></div></div><div className="nav-item-list">{c.items.map(i=><button key={i.id} onClick={()=>onOpen(i.id)} className="nav-item tap"><span className="nav-item-copy"><span className="nav-item-title">{i.title}</span><span className="nav-item-description">{i.body}</span></span><span className="nav-item-arrow"><ChevronRight size={17}/></span></button>)}</div></section>)}</div></>}
function findNav(nav:NavCategory[],id:string){for(const c of nav){const x=c.items.find(i=>i.id===id);if(x)return x}return undefined}
function NavModal({item,onClose}:{item:any;onClose:()=>void}){return <Modal title={item?.title||'Материал'} onClose={onClose}>{item?<div className="space-y-4"><div className="material-card"><div className="material-body">{item.body}</div></div><div className="text-xs text-white/35">Материал из навигации</div></div>:<Empty title="Материал не найден" text="Запись была удалена или скрыта."/>}</Modal>}
function TasksView({data,refresh,toast,onOpen}:{data:Data;refresh:()=>Promise<void>;toast:(s:string)=>void;onOpen:(id:string)=>void}){const [filter,setFilter]=useState<'ALL'|TaskStatus>('ALL');const [search,setSearch]=useState('');const [newOpen,setNewOpen]=useState(false);const tasks=data.tasks.filter(t=>(filter==='ALL'||t.status===filter)&&(`${t.title} ${t.description}`).toLowerCase().includes(search.toLowerCase()));return <><PageTitle title="Задания"/><div className="flex gap-2"><div className="glass flex flex-1 items-center gap-2 rounded-2xl px-3"><Search size={17} className="text-white/35"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск задания" className="w-full bg-transparent py-3 outline-none placeholder:text-white/25"/></div><button onClick={()=>setNewOpen(true)} className="glass rounded-2xl p-3"><Plus size={20}/></button></div><div className="mt-3 flex gap-2 overflow-x-auto pb-1">{[['ALL','Все'],['NEW','Новые'],['IN_PROGRESS','В работе'],['DONE','Готово']].map(([k,l])=><button key={k} onClick={()=>setFilter(k as any)} className={cls('rounded-full border px-3 py-2 text-xs whitespace-nowrap',filter===k?'border-violet-300/30 bg-violet-400/15':'border-white/10 bg-white/[.03]')}>{l}</button>)}</div><div className="mt-4 space-y-3">{tasks.map(t=><button key={t.id} onClick={()=>onOpen(t.id)} className="glass tap w-full rounded-3xl p-4 text-left"><div className="flex items-start gap-3"><div className="mt-0.5 rounded-xl bg-white/5 p-2"><Target size={18}/></div><div className="flex-1"><div className="font-bold">{t.title}</div><div className="mt-1 text-sm text-white/45">{t.description}</div><div className="mt-3 flex gap-2"><StatusBadge status={t.status}/><span className="status-pill status-pill-muted">{priorityName(t.priority)}</span></div></div><ChevronRight size={17} className="text-white/25"/></div></button>)}{!tasks.length&&<Empty title="Заданий нет" text="Измените фильтр или создайте новое задание."/>}</div>{newOpen&&<NewTask onClose={()=>setNewOpen(false)} refresh={refresh} toast={toast}/>}</>}
function Badge({text}:{text:string}){return <span className="status-pill status-pill-muted">{text}</span>}; function StatusBadge({status}:{status:TaskStatus}){return <span className={cls('status-pill',status==='DONE'?'status-pill-success':status==='IN_PROGRESS'?'status-pill-warning':'status-pill-muted')}>{statusName(status)}</span>};function statusName(s:TaskStatus){return s==='NEW'?'Новое':s==='IN_PROGRESS'?'В работе':'Готово'}function priorityName(s:string){return PRIORITY_NAMES[s]||s}
function NewTask({onClose,refresh,toast}:{onClose:()=>void;refresh:()=>Promise<void>;toast:(s:string)=>void}){const [title,setTitle]=useState('');const [description,setDescription]=useState('');const [priority,setPriority]=useState('MEDIUM');const save=async()=>{try{await api('/api/tasks',{method:'POST',body:JSON.stringify({title,description,priority})});toast('Задание создано');onClose();await refresh()}catch(e){toast((e as Error).message)}};return <Modal title="Новое задание" onClose={onClose}><div className="space-y-3"><Field label="Название"><input value={title} onChange={e=>setTitle(e.target.value)} className="input" placeholder="Например, проверить раздел"/></Field><Field label="Описание"><textarea value={description} onChange={e=>setDescription(e.target.value)} className="input min-h-28" placeholder="Что нужно сделать?"/></Field><Field label="Приоритет"><CustomSelect value={priority} onChange={setPriority} placeholder="Выберите приоритет" options={[{value:"LOW",label:"Низкий"},{value:"MEDIUM",label:"Средний"},{value:"HIGH",label:"Высокий"}]}/></Field><Button variant="primary" onClick={save}>Создать</Button></div></Modal>}
function TaskModal({task,onClose,refresh,toast}:{task?:Task;onClose:()=>void;refresh:()=>Promise<void>;toast:(s:string)=>void}){if(!task)return <Modal title="Задание" onClose={onClose}><Empty title="Не найдено" text="Задание недоступно."/></Modal>;const set=async(status:TaskStatus)=>{try{await api(`/api/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({status})});toast('Статус обновлён');onClose();await refresh()}catch(e){toast((e as Error).message)}};return <Modal title={task.title} onClose={onClose}><div className="space-y-4"><p className="leading-7 text-white/75">{task.description}</p><div className="flex gap-2"><StatusBadge status={task.status}/><span className="status-pill status-pill-muted">{priorityName(task.priority)}</span></div><div className="grid grid-cols-2 gap-2"><Button onClick={()=>set('IN_PROGRESS')}>В работу</Button><Button variant="primary" onClick={()=>set(task.status==='DONE'?'NEW':'DONE')}>{task.status==='DONE'?'Вернуть':'Выполнено'}</Button></div></div></Modal>}
function AfkView({data,refresh,toast}:{data:Data;refresh:()=>Promise<void>;toast:(s:string)=>void}){const mine=data.afk.find(a=>a.userId===data.me.id&&(a.status==='PENDING'||(a.status==='APPROVED'&&a.active)));const [reason,setReason]=useState('');const [from,setFrom]=useState('');const [until,setUntil]=useState('');const save=async()=>{try{await api('/api/afk',{method:'POST',body:JSON.stringify({reason,startsAt:new Date(from).toISOString(),endsAt:new Date(until).toISOString()})});toast('Заявка на AFK отправлена');setReason('');setFrom('');setUntil('');await refresh()}catch(e){toast((e as Error).message)}};const off=async()=>{try{await api('/api/afk',{method:'DELETE'});toast('AFK снят');await refresh()}catch(e){toast((e as Error).message)}};const pending=data.afk.filter(a=>a.status==='PENDING');const review=async(id:string,decision:'APPROVED'|'REJECTED')=>{try{await api('/api/afk',{method:'PATCH',body:JSON.stringify({requestId:id,decision})});toast(decision==='APPROVED'?'AFK одобрен':'AFK отклонён');await refresh()}catch(e){toast((e as Error).message)}};return <><PageTitle title="AFK"/><div className="glass rounded-3xl p-5">{mine?.status==='APPROVED'?<><div className="flex items-center gap-3"><div className="rounded-2xl bg-emerald-400/10 p-3 text-emerald-200"><Clock3/></div><div><div className="font-bold">AFK одобрен</div><div className="text-sm text-white/40">{mine.reason}</div></div><span className="status-pill status-pill-success ml-auto">Одобрено</span></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><div className="rounded-2xl bg-white/[.035] p-3">Начало<br/><b>{new Date(mine.startsAt).toLocaleString('ru-RU')}</b></div><div className="rounded-2xl bg-white/[.035] p-3">Конец<br/><b>{new Date(mine.endsAt).toLocaleString('ru-RU')}</b></div></div><div className="mt-3"><Button variant="danger" onClick={off}>Снять AFK</Button></div></>:mine?.status==='PENDING'?<div><div className="status-pill status-pill-warning inline-flex">Ожидает одобрения</div><div className="mt-3 text-sm text-white/55">{mine.reason}</div><div className="mt-2 text-xs text-white/35">{new Date(mine.startsAt).toLocaleString('ru-RU')} → {new Date(mine.endsAt).toLocaleString('ru-RU')}</div></div>:data.me.stars<=3?<div className="space-y-3"><div className="text-sm text-white/45">Заявка доступна для 1–3 звёзд. После отправки её увидят 4–5 звёзд. Достаточно одного одобрения.</div><Field label="Дата и время начала"><input type="datetime-local" value={from} onChange={e=>setFrom(e.target.value)} className="input"/></Field><Field label="Дата и время окончания"><input type="datetime-local" value={until} onChange={e=>setUntil(e.target.value)} className="input"/></Field><Field label="Причина"><textarea value={reason} onChange={e=>setReason(e.target.value)} className="input min-h-24" placeholder="Причина отсутствия"/></Field><Button variant="primary" onClick={save} disabled={!from||!until||!reason}>Отправить на проверку</Button></div>:<div className="text-sm text-white/45">Для 4–5 звёзд заявки на AFK не создаются — вы одобряете заявки сотрудников.</div>}</div>{data.me.stars>=4&&<div className="mt-6"><div className="mb-3 font-bold">Заявки на проверку</div><div className="space-y-2">{pending.map(a=><div key={a.id} className="glass rounded-2xl p-4"><div className="font-semibold">@{data.users.find(u=>u.id===a.userId)?.username||'user'}</div><div className="mt-1 text-sm text-white/45">{a.reason}</div><div className="mt-2 text-xs text-white/35">{new Date(a.startsAt).toLocaleString('ru-RU')} → {new Date(a.endsAt).toLocaleString('ru-RU')}</div><div className="mt-3 grid grid-cols-2 gap-2"><Button variant="danger" onClick={()=>review(a.id,'REJECTED')}>Отказать</Button><Button variant="primary" onClick={()=>review(a.id,'APPROVED')}>Одобрить</Button></div></div>)}{!pending.length&&<Empty title="Новых заявок нет" text="Новые заявки появятся здесь и в колоколе."/>}</div></div>}<div className="mt-6 mb-3 font-bold">Сейчас AFK</div><div className="space-y-2">{data.afk.filter(a=>a.status==='APPROVED'&&a.active).map(a=><div key={a.id} className="glass rounded-2xl p-3"><div className="font-semibold">@{data.users.find(u=>u.id===a.userId)?.username||'user'}</div><div className="text-sm text-white/40">{a.reason} · до {new Date(a.endsAt).toLocaleString('ru-RU')}</div></div>)}{!data.afk.some(a=>a.status==='APPROVED'&&a.active)&&<Empty title="Никого нет в AFK" text="Активные записи появятся здесь."/>}</div></>}
function ProfileView({data,refresh,toast,onAdmin,compact,setCompact}:{data:Data;refresh:()=>void;toast:(s:string)=>void;onAdmin:()=>void;compact:boolean;setCompact:(v:boolean)=>void}){const [edit,setEdit]=useState(false);const [settings,setSettings]=useState(false);return <><PageTitle title="Мой профиль"/><div className="glass rounded-3xl p-5"><div className="flex items-center gap-4"><div className="h-16 w-16 shrink-0 overflow-hidden rounded-2xl bg-gradient-to-br from-violet-500/30 to-cyan-400/10">{data.me.avatarUrl?<img src={data.me.avatarUrl} alt="" className="h-full w-full object-cover"/>:<div className="grid h-full w-full place-items-center text-xl font-black">{data.me.firstName[0]}</div>}</div><div className="flex-1"><div className="text-lg font-black">{data.me.firstName} {data.me.lastName}</div><div className="text-sm text-white/45">@{data.me.username}</div><div className="mt-1 text-[11px] text-white/25">Telegram ID: {data.me.telegramId}</div><div className="mt-2 flex items-center gap-2"><Stars n={data.me.stars}/><span className="text-xs text-violet-100">{starName(data.me.stars)}</span>{(()=>{const dp=defaultPrefix(data.me.stars);return <span className={`status-chip status-chip-${data.me.prefixStyle||dp.style}`} style={{'--chip-color':data.me.prefixColor||dp.color} as React.CSSProperties}>{data.me.prefix||dp.prefix}</span>})()}</div></div></div><div className="mt-5 grid grid-cols-2 gap-2">{[['Проверок',data.stats.checks],['Средний результат',`${data.stats.avg}%`],['Сообщений',data.stats.messages],['Текущих заданий',data.tasks.filter(t=>t.status!=='DONE').length]].map(([a,b])=><div key={a as string} className="rounded-2xl bg-white/[.035] p-3"><div className="text-xs text-white/40">{a}</div><div className="mt-1 text-lg font-bold">{b}</div></div>)}</div></div><div className="mt-4 space-y-2"><Button onClick={()=>setEdit(true)}><span className="flex items-center gap-2"><Edit3 size={17}/>Изменить профиль</span></Button><Button onClick={()=>setSettings(true)}><span className="flex items-center gap-2"><Settings size={17}/>Настройки</span></Button>{data.permissions.some(p=>p.startsWith('MANAGE_'))&&<Button variant="primary" onClick={onAdmin}><span className="flex items-center gap-2"><Shield size={17}/>Админ-панель</span></Button>}{process.env.NEXT_PUBLIC_DEMO_MODE==='true'&&<Button onClick={async()=>{const r=await api('/api/demo/switch',{method:'POST'});toast(`Активен @${r.me.username}`);refresh()}}>Сменить demo-пользователя</Button>}</div>{edit&&<EditProfile data={data} onClose={()=>setEdit(false)} refresh={refresh} toast={toast}/>} {settings&&<SettingsModal onClose={()=>setSettings(false)} toast={toast} compact={compact} setCompact={setCompact}/>}</>}
function EditProfile({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const [first,setFirst]=useState(data.me.firstName);const [last,setLast]=useState(data.me.lastName);const username=data.me.username;const save=async()=>{try{await api('/api/profile',{method:'PATCH',body:JSON.stringify({firstName:first,lastName:last})});toast('Профиль сохранён');onClose();refresh()}catch(e){toast((e as Error).message)}};return <Modal title="Изменить профиль" onClose={onClose}><div className="space-y-3"><Field label="Имя"><input className="input" value={first} onChange={e=>setFirst(e.target.value)}/></Field><Field label="Фамилия"><input className="input" value={last} onChange={e=>setLast(e.target.value)}/></Field><Field label="Username"><input className="input" value={username} disabled /></Field><Button variant="primary" onClick={save}>Сохранить</Button></div></Modal>}
function SettingsModal({onClose,toast,compact,setCompact}:{onClose:()=>void;toast:(s:string)=>void;compact:boolean;setCompact:(v:boolean)=>void}){const [haptic,setHaptic]=useState(true);useEffect(()=>{try{const x=JSON.parse(localStorage.getItem('tc_settings')||'{}');if(typeof x.haptic==='boolean')setHaptic(x.haptic)}catch{}},[]);const save=()=>{localStorage.setItem('tc_settings',JSON.stringify({haptic,compact}));setCompact(compact);if(haptic)tg()?.HapticFeedback?.notificationOccurred?.('success');toast('Настройки сохранены');onClose()};return <Modal title="Настройки" onClose={onClose}><div className="space-y-3"><div className="rounded-2xl border border-white/10 bg-white/[.025] p-3 text-xs leading-5 text-white/45">Компактный режим уменьшает вертикальные отступы и высоту карточек/списков, чтобы на экране помещалось больше информации. Данные и функции не меняются.</div><button onClick={()=>{setHaptic(!haptic);tg()?.HapticFeedback?.impactOccurred?.('light')}} className="glass tap flex w-full items-center rounded-2xl p-4 text-left"><span className="flex-1 font-semibold">Виброотклик</span><span className={cls('settings-switch',haptic?'settings-switch-on':'')}><span/></span></button><button onClick={()=>setCompact(!compact)} className="glass tap flex w-full items-center rounded-2xl p-4 text-left"><span className="flex-1"><span className="block font-semibold">Компактный режим</span><span className="mt-1 block text-xs text-white/35">Меньше отступов и плотнее списки</span></span><span className={cls('settings-switch',compact?'settings-switch-on':'')}><span/></span></button><Button variant="primary" onClick={save}>Сохранить</Button></div></Modal>}
function AdminView({data,refresh,toast,onOpen,navTo,openAdminList,openAdminAutomation}:{data:Data;refresh:()=>void;toast:(s:string)=>void;onOpen:(k:string)=>void;navTo:(t:string)=>void;openAdminList:()=>void;openAdminAutomation:()=>void}){
 const cards=[['Пользователи',data.users.length,'user',Users],['Навигация',data.nav.reduce((a,c)=>a+c.items.length,0),'nav-admin',ListChecks],['Задания',data.tasks.length,'tasks',Target],['Статистика',`${data.stats.avg}%`,'stats',Activity],['Журнал действий',data.audit.length,'audit',Menu],['AFK',data.afk.filter(a=>a.active).length,'admin-afk',Clock3],['Права',10,'role',KeyRound]] as const;
 return <>
  <button onClick={openAdminList} className="glass tap mb-3 flex w-full items-center gap-4 rounded-3xl p-4 text-left"><div className="rounded-2xl bg-violet-400/10 p-3 text-violet-200"><Shield size={22}/></div><div className="flex-1"><div className="font-bold">Список админов</div><div className="mt-1 text-sm text-white/45">Чёрный и Синий чат · синхронизация Iris</div></div><ChevronRight size={18} className="text-white/35"/></button>
  <button onClick={openAdminAutomation} className="glass tap mb-3 flex w-full items-center gap-4 rounded-3xl p-4 text-left"><div className="rounded-2xl bg-emerald-400/10 p-3 text-emerald-200"><Activity size={22}/></div><div className="flex-1"><div className="font-bold">Автоматизация админов</div><div className="mt-1 text-sm text-white/45">Сканирование 2 чатов и автообновление из Iris</div></div><ChevronRight size={18} className="text-white/35"/></button>
  {data.me.stars>=5&&<button onClick={()=>onOpen('prefix')} className="glass tap mb-3 flex w-full items-center gap-4 rounded-3xl p-4 text-left"><div className="rounded-2xl bg-fuchsia-400/10 p-3 text-fuchsia-200"><KeyRound size={22}/></div><div className="flex-1"><div className="font-bold">Префиксы и статусы</div><div className="mt-1 text-sm text-white/45">Создать свой префикс, выбрать цвет и стиль</div></div><ChevronRight size={18} className="text-white/35"/></button>}
  <PageTitle title="Админ-панель"/>
  <div className="grid grid-cols-2 gap-3">{cards.map(([a,b,k,I])=><button key={k} onClick={()=>k==='tasks'?onOpen('admin-tasks'):onOpen(k)} className="glass tap rounded-3xl p-4 text-left"><div className="mb-5 inline-flex rounded-2xl bg-violet-400/10 p-2.5 text-violet-200"><I size={18}/></div><div className="text-sm font-semibold">{a}</div><div className="mt-1 text-2xl font-black">{b}</div><ChevronRight size={16} className="float-right text-white/25"/></button>)}</div>
  <div className="glass mt-4 rounded-3xl p-4"><div className="flex items-center gap-3"><Shield size={20}/><div><b>Система прав активна</b><div className="text-xs text-white/40">Доступ к действиям проверяется по назначенным правам</div></div></div><div className="mt-3 flex flex-wrap gap-2">{data.permissions.map(p=><span key={p} className="rounded-full border border-white/10 px-2 py-1 text-[9px] text-white/50">{PERMISSION_NAMES[p]||p}</span>)}</div></div>
  {data.permissions.includes('MANAGE_USERS')&&<div className="mt-4"><Button onClick={()=>onOpen('user')}><Users size={16}/> Управление пользователями</Button></div>}
  {data.permissions.includes('MANAGE_USERS')&&<div className="mt-4 grid grid-cols-2 gap-2"><Button onClick={()=>onOpen('role')}>Роли и права</Button><Button onClick={()=>onOpen('prefix')}>Префиксы</Button><Button onClick={()=>onOpen('audit')}>Журнал действий</Button></div>}
  <div className="mt-2 grid grid-cols-2 gap-2"><Button onClick={()=>onOpen('stats')}>Статистика</Button><Button onClick={()=>{toast('Проверка прав выполнена');refresh()}}>Проверить доступ</Button></div>
 </>
}
function UserModal({data,userId,onClose,refresh,toast}:{data:Data;userId:string;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const users=data.users;const [u,setU]=useState(data.users.find(x=>x.id===userId)||data.users[0]);const save=async()=>{try{await api(`/api/admin/users/${u.id}`,{method:'PATCH',body:JSON.stringify({stars:u.stars,role:u.role})});toast('Пользователь обновлён');onClose();refresh()}catch(e){toast((e as Error).message)}};return <Modal title="Пользователи" onClose={onClose}><div className="space-y-2">{users.map(x=><button key={x.id} onClick={()=>setU(x)} className={cls('glass w-full rounded-2xl p-3 text-left',u.id===x.id?'border-violet-300/30':'')}><div className="flex items-center gap-3"><div className="flex-1"><b>@{x.username}</b><div className="text-xs text-white/40">{starName(x.stars)}</div></div><Stars n={x.stars} size={12}/></div></button>)}<div className="mt-4 border-t border-white/10 pt-4"><div className="text-sm font-bold">Редактирование @{u.username}</div><div className="mt-3 text-xs text-white/40">Ранг</div><div className="mt-2 flex gap-1">{[1,2,3,4,5].map(n=><button key={n} onClick={()=>setU({...u,stars:n,role:roleFrom(n)})} className={cls('rounded-xl border p-2',u.stars===n?'border-amber-300/30 bg-amber-300/10':'border-white/10')}><Star size={18} fill={n<=u.stars?'currentColor':'transparent'} className="text-amber-300"/></button>)}</div><div className="mt-3"><CustomSelect value={u.role} onChange={value=>setU({...u,role:value as any})} placeholder="Выберите роль" options={Object.entries(ROLE_NAMES).map(([value,label])=>({value,label}))}/></div><div className="mt-3"><Button variant="primary" onClick={save}>Сохранить</Button></div></div></div></Modal>}
function roleFrom(n:number):RoleCode{return n>=5?'SUPER_ADMIN':n===4?'SENIOR_ADMIN':n===3?'SENIOR_STAFF':n===2?'JUNIOR_STAFF':'USER'}
function RoleModal({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const [selected,setSelected]=useState<RoleCode>(data.me.role);const [perms,setPerms]=useState<string[]>(data.rolePermissions[selected]||[]);useEffect(()=>setPerms(data.rolePermissions[selected]||[]),[selected,data.rolePermissions]);const save=async()=>{try{await api('/api/admin/roles',{method:'PATCH',body:JSON.stringify({role:selected,permissions:perms})});toast('Права роли сохранены');refresh();onClose()}catch(e){toast((e as Error).message)}};return <Modal title="Роли и права" onClose={onClose}><div className="space-y-2">{Object.entries(ROLE_NAMES).map(([k,v])=><button key={k} onClick={()=>setSelected(k as any)} className={cls('glass w-full rounded-2xl p-3 text-left',selected===k?'border-violet-300/30 bg-violet-400/[.06]':'')}><div className="font-semibold">{v}</div><div className="text-xs text-white/40">{(data.rolePermissions[k as RoleCode]||[]).length} прав</div></button>)}</div><div className="mt-4 rounded-3xl border border-white/10 bg-white/[.02] p-4"><div className="font-bold">Права · {ROLE_NAMES[selected]}</div><div className="mt-3 grid gap-2">{['VIEW_CONTENT','EDIT_CONTENT','MANAGE_NAVIGATION','MANAGE_PREFIXES','MANAGE_USERS','MANAGE_TASKS','MANAGE_AFK','VIEW_STATISTICS','MANAGE_STATISTICS','VIEW_AUDIT_LOG'].map(p=><button key={p} type="button" onClick={()=>setPerms(x=>x.includes(p)?x.filter(v=>v!==p):[...x,p])} className={cls('permission-toggle flex w-full items-center gap-3 rounded-2xl border p-3 text-left',perms.includes(p)?'permission-toggle-on border-violet-300/30 bg-violet-400/[.10]':'border-white/10 bg-white/[.03]')}><span className={cls('permission-switch',perms.includes(p)?'permission-switch-on':'')}><span/></span><span className="min-w-0 flex-1 text-xs font-semibold">{PERMISSION_NAMES[p]||p}</span><span className={cls('text-[10px] font-bold',perms.includes(p)?'text-violet-200':'text-white/25')}>{perms.includes(p)?'ВКЛ':'ВЫКЛ'}</span></button>)}</div></div><div className="mt-4"><Button variant="primary" onClick={save}>Сохранить права</Button></div></Modal>}
function AuditModal({logs,onClose}:{logs:AuditLog[];onClose:()=>void}){return <Modal title="Журнал действий" onClose={onClose}><div className="space-y-2">{logs.slice(0,30).map(l=><div key={l.id} className="rounded-2xl bg-white/[.035] p-3"><div className="flex justify-between gap-2"><b className="text-sm">{l.action}</b><span className="text-[10px] text-white/35">{new Date(l.createdAt).toLocaleString('ru-RU')}</span></div><div className="mt-1 text-xs text-white/45">{l.entity} {l.entityId||''}</div></div>)}</div></Modal>}
function StatsView({data}:{data:Data}){const [showCheck,setShowCheck]=useState(false);const [target,setTarget]=useState('');const admins=data.admins;const myChecks=data.checks;const adminStats=admins.map(a=>{const cs=myChecks.filter(c=>c.adminId===a.user.id);const avg=cs.length?Math.round(cs.reduce((n,c)=>n+(c.maxScore?c.score/c.maxScore*100:0),0)/cs.length):0;const last=cs[0];return {...a,checks:cs.length,avg,last}});return <><PageTitle title="Итоги проверки"/><div className="glass rounded-3xl p-5"><div className="flex items-center gap-3"><div className="rounded-2xl bg-violet-400/10 p-3 text-violet-200"><CheckCircle2 size={22}/></div><div><div className="font-bold">Проверки администраторов</div><div className="text-sm text-white/40">Данные берутся напрямую из вкладки «Админы».</div></div></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="stat-card"><div>Проверок</div><b>{data.stats.checks}</b></div><div className="stat-card"><div>Средний результат</div><b>{data.stats.avg}%</b></div><div className="stat-card"><div>Сообщений</div><b>{data.stats.messages}</b></div><div className="stat-card"><div>Идеальных</div><b>{data.checks.filter(c=>c.score===c.maxScore).length}</b></div></div></div><div className="mt-4 space-y-3">{adminStats.map(a=><div key={a.id} className="glass rounded-3xl p-4"><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><b>{a.user.firstName} {a.user.lastName}</b>{a.user.prefix&&<span className={`status-chip status-chip-${a.user.prefixStyle||'soft'}`} style={{'--chip-color':a.user.prefixColor||'#a78bfa'} as React.CSSProperties}>{a.user.prefix}</span>}</div><div className="mt-1 text-xs text-white/40">@{a.user.username} · {a.groupTitle} · {a.rankTitle}</div><div className="mt-3 flex flex-wrap gap-2"><span className="status-pill status-pill-muted">Проверок: {a.checks}</span><span className={`status-pill ${a.avg===100?'status-pill-success':'status-pill-warning'}`}>Среднее: {a.avg}%</span></div></div>{data.me.stars>=4&&<button onClick={()=>{setTarget(a.user.id);setShowCheck(true)}} className="rounded-xl border border-violet-300/20 bg-violet-500/10 px-3 py-2 text-xs font-bold">Внести</button>}</div>{a.last&&<div className="mt-3 rounded-2xl border border-white/8 bg-white/[.025] p-3"><div className="flex items-center justify-between text-xs"><span className="text-white/40">Последняя проверка</span><span className="text-white/30">{new Date(a.last.checkedAt).toLocaleDateString('ru-RU')}</span></div><div className="mt-2 grid grid-cols-2 gap-2 text-sm"><div><span className="text-white/35">Сообщения</span><b className="ml-2">{a.last.messages}/{a.last.messagesMax}</b></div><div><span className="text-white/35">Ответы</span><b className="ml-2">{a.last.replies}/{a.last.repliesMax}</b></div></div>{a.last.repeatNotes.length>0&&<div className="mt-3 rounded-xl border border-amber-300/10 bg-amber-300/5 p-3 text-xs text-amber-100"><b>Что повторить</b><ul className="mt-1 list-disc pl-4">{a.last.repeatNotes.map((n,i)=><li key={i}>{n}</li>)}</ul></div>}{a.last.repeatNotes.length===0&&<div className="mt-3 status-pill status-pill-success inline-flex">Идеальный результат · замечаний нет</div>}</div>}</div>)}{!adminStats.length&&<Empty title="Админов пока нет" text="Список загружается из вкладки «Админы» и Iris."/>}</div>{showCheck&&<InlineCheckForm data={data} targetId={target} onClose={()=>setShowCheck(false)}/>}</>}
function InlineCheckForm({data,targetId,onClose}:{data:Data;targetId:string;onClose:()=>void}){const [messages,setMessages]=useState('8'),[messagesMax,setMessagesMax]=useState('8'),[replies,setReplies]=useState('8'),[repliesMax,setRepliesMax]=useState('8'),[quality,setQuality]=useState('2'),[qualityMax,setQualityMax]=useState('2'),[note,setNote]=useState(''),[busy,setBusy]=useState(false);const save=async()=>{setBusy(true);try{const r=await api('/api/checks',{method:'POST',body:JSON.stringify({adminId:targetId,messages:+messages,messagesMax:+messagesMax,replies:+replies,repliesMax:+repliesMax,items:[{id:'quality',label:'Качество',score:+quality,maxScore:+qualityMax,note:note||undefined}]})});if(!r.ok)throw new Error(r.error);onClose();location.reload()}catch(e){alert((e as Error).message)}finally{setBusy(false)}};return <Modal title="Новая проверка" onClose={onClose}><div className="grid grid-cols-2 gap-3"><Field label="Сообщения"><input className="input" type="number" value={messages} onChange={e=>setMessages(e.target.value)}/></Field><Field label="Из"><input className="input" type="number" value={messagesMax} onChange={e=>setMessagesMax(e.target.value)}/></Field><Field label="Ответы"><input className="input" type="number" value={replies} onChange={e=>setReplies(e.target.value)}/></Field><Field label="Из"><input className="input" type="number" value={repliesMax} onChange={e=>setRepliesMax(e.target.value)}/></Field><Field label="Качество"><input className="input" type="number" value={quality} onChange={e=>setQuality(e.target.value)}/></Field><Field label="Из"><input className="input" type="number" value={qualityMax} onChange={e=>setQualityMax(e.target.value)}/></Field></div><Field label="Что повторить (только если не идеально)"><textarea className="input mt-1 min-h-20" value={note} onChange={e=>setNote(e.target.value)} placeholder="Оставь пустым для идеального результата"/></Field><Button variant="primary" onClick={save} disabled={busy}>{busy?'Сохранение…':'Сохранить'}</Button></Modal>}
function StatsModal({data,onClose}:{data:Data;onClose:()=>void}){return <Modal title="Статистика" onClose={onClose}><div className="grid grid-cols-2 gap-3">{[['Проверки',data.stats.checks],['Средний результат',`${data.stats.avg}%`],['Сообщения',data.stats.messages],['Идеальные',data.checks.filter(c=>c.score===c.maxScore).length]].map(([a,b])=><div key={a as string} className="glass rounded-2xl p-4"><div className="text-xs text-white/40">{a}</div><div className="mt-2 text-2xl font-black">{b}</div></div>)}</div></Modal>}
function NotificationsView({data,refresh}:{data:Data;refresh:()=>Promise<void>}){const [busy,setBusy]=useState(false);const mark=async(id?:string)=>{setBusy(true);try{await api('/api/notifications',{method:'PATCH',body:JSON.stringify(id?{id}:{all:true})});await refresh()}finally{setBusy(false)}};return <><PageTitle title="Уведомления"/><div className="mb-3 flex justify-end"><button disabled={busy} onClick={()=>mark()} className="text-xs text-white/45">Отметить всё прочитанным</button></div><div className="space-y-3">{data.notifications.map(n=><button key={n.id} onClick={()=>mark(n.id)} className={cls('glass w-full rounded-3xl p-4 text-left',!n.read?'border-violet-300/25':'')}><div className="flex gap-3"><div className="rounded-2xl bg-violet-400/10 p-3"><Bell size={18}/></div><div className="flex-1"><div className="font-bold">{n.title}</div><div className="mt-1 text-sm leading-6 text-white/50">{n.body}</div><div className="mt-2 text-[10px] text-white/25">{new Date(n.createdAt).toLocaleString('ru-RU')}</div></div>{!n.read&&<span className="mt-1 h-2 w-2 rounded-full bg-violet-300"/>}</div></button>)}{!data.notifications.length&&<Empty title="Уведомлений нет" text="Здесь появятся решения по AFK и другие важные сообщения."/>}</div></>}
function AdminNavModal({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const [cat,setCat]=useState('');const [title,setTitle]=useState('');const [body,setBody]=useState('');const save=async()=>{try{await api('/api/admin/navigation',{method:'POST',body:JSON.stringify({categoryId:cat,title,body})});toast('Тема добавлена');refresh();setTitle('');setBody('')}catch(e){toast((e as Error).message)}};return <Modal title="Управление навигацией" onClose={onClose}><div className="w-full min-w-0 space-y-3">{data.nav.map(c=><div key={c.id} className="w-full min-w-0 rounded-2xl border border-white/8 bg-white/[.035] p-3"><div className="font-bold">{c.title}</div><div className="mt-2 space-y-2">{c.items.map(i=><div key={i.id} className="min-w-0 rounded-xl border border-white/7 bg-black/10 p-3"><div className="break-words text-sm font-semibold">{i.title}</div><div className="mt-1 break-words text-xs leading-5 text-white/40">{i.body}</div></div>)}</div></div>)}<Field label="Категория"><CustomSelect value={cat} onChange={setCat} placeholder="Выберите категорию" options={data.nav.map(c=>({value:c.id,label:c.title,description:`${c.items.length} ${c.items.length===1?'тема':'тем'}`}))}/></Field><Field label="Название темы"><input value={title} onChange={e=>setTitle(e.target.value)} className="input"/></Field><Field label="Текст"><textarea value={body} onChange={e=>setBody(e.target.value)} className="input min-h-24"/></Field><Button variant="primary" onClick={save}>Добавить тему</Button></div></Modal>}
function PrefixModal({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const admins=data.users.filter(x=>x.stars>=1);const [u,setU]=useState(admins.find(x=>x.id===data.me.id)||admins[0]);const [prefix,setPrefix]=useState(u?.prefix||'');const [color,setColor]=useState(u?.prefixColor||({1:'#94a3b8',2:'#22d3ee',3:'#60a5fa',4:'#c084fc',5:'#fbbf24'} as Record<number,string>)[u?.stars||1]);const [style,setStyle]=useState<'soft'|'solid'|'outline'|'glow'>(u?.prefixStyle||'soft');const [status,setStatus]=useState(u?.status||'Активен');const pick=(id:string)=>{const next=data.users.find(x=>x.id===id)!;setU(next);setPrefix(next.prefix||'');setColor(next.prefixColor||({1:'#94a3b8',2:'#22d3ee',3:'#60a5fa',4:'#c084fc',5:'#fbbf24'} as Record<number,string>)[next.stars]);setStyle(next.prefixStyle||'soft');setStatus(next.status||'Активен')};const save=async()=>{try{await api('/api/prefixes',{method:'PATCH',body:JSON.stringify({userId:u.id,prefix,color,status,style})});toast('Префикс и дизайн сохранены');await refresh();onClose()}catch(e){toast((e as Error).message)}};const chipClass=`status-chip status-chip-${style}`;return <Modal title="Префиксы и статусы" onClose={onClose}><div className="space-y-4"><div className="rounded-2xl border border-violet-300/10 bg-violet-400/[.04] p-3 text-xs leading-5 text-white/50"><b className="text-white/80">Только 5 звёзд.</b> Для каждого ранга уже задан индивидуальный префикс и цвет. Здесь можно заменить его на свой и выбрать стиль.</div><Field label="Администратор"><CustomSelect value={u.id} onChange={pick} placeholder="Выберите администратора" options={admins.map(x=>({value:x.id,label:`@${x.username}`,description:starName(x.stars)}))}/></Field><Field label="Свой префикс"><input className="input" value={prefix} onChange={e=>setPrefix(e.target.value)} placeholder="Например: Наставник" maxLength={24}/></Field><Field label="Статус"><input className="input" value={status} onChange={e=>setStatus(e.target.value)} placeholder="Активен" maxLength={30}/></Field><Field label="Цвет"><div className="flex gap-2"><input type="color" value={color} onChange={e=>setColor(e.target.value)} className="h-12 w-16 rounded-xl border border-white/10 bg-transparent"/><input className="input" value={color} onChange={e=>setColor(e.target.value)}/></div></Field><Field label="Стиль"><CustomSelect value={style} onChange={v=>setStyle(v as any)} placeholder="Выберите стиль" options={[{value:'soft',label:'Мягкий',description:'Прозрачный фон'},{value:'solid',label:'Заполненный',description:'Яркий фон'},{value:'outline',label:'Контур',description:'Только контур'},{value:'glow',label:'Свечение',description:'Акцентное свечение'}]}/></Field><div className="rounded-2xl border border-white/10 bg-white/[.03] p-4"><div className="text-xs text-white/35">Предпросмотр</div><div className="mt-3 flex flex-wrap items-center gap-2"><span className={chipClass} style={{'--chip-color':color} as React.CSSProperties}>{prefix||'Префикс'}</span><span className="status-pill status-pill-success">{status||'Статус'}</span></div></div><Button variant="primary" onClick={save} disabled={!u||!prefix.trim()}>Сохранить префикс</Button></div></Modal>}
function AdminTasksModal({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const del=async(id:string)=>{try{await api(`/api/tasks/${id}`,{method:'DELETE'});toast('Задание удалено');refresh()}catch(e){toast((e as Error).message)}};return <Modal title="Управление заданиями" onClose={onClose}><div className="space-y-2">{data.tasks.map(t=><div key={t.id} className="glass rounded-2xl p-3"><div className="flex items-center gap-2"><div className="flex-1"><b>{t.title}</b><div className="text-xs text-white/40">{statusName(t.status)} · {priorityName(t.priority)}</div></div><button onClick={()=>del(t.id)} className="rounded-xl p-2 text-red-300"><X size={17}/></button></div></div>)}</div></Modal>}
function AdminAfkModal({data,onClose,refresh,toast}:{data:Data;onClose:()=>void;refresh:()=>void;toast:(s:string)=>void}){const active=data.afk.filter(a=>a.active);const stop=async(userId:string)=>{try{await api('/api/afk',{method:'PATCH',body:JSON.stringify({userId,active:false})});toast('AFK пользователя снят');refresh()}catch(e){toast((e as Error).message)}};return <Modal title="Управление AFK" onClose={onClose}><div className="space-y-2">{active.map(a=><div key={a.id} className="glass rounded-2xl p-4"><div className="flex items-center gap-3"><div className="flex-1"><b>@{data.users.find(u=>u.id===a.userId)?.username||'user'}</b><div className="text-xs text-white/40">{a.reason} · {a.endsAt?new Date(a.endsAt).toLocaleString('ru-RU'):'без срока'}</div></div><button onClick={()=>stop(a.userId)} className="rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-2 text-xs text-red-200">Снять</button></div></div>)}{!active.length&&<Empty title="AFK пуст" text="Активных записей нет."/>}</div></Modal>}
function CustomSelect({value,onChange,options,placeholder}:{value:string;onChange:(value:string)=>void;options:{value:string;label:string;description?:string}[];placeholder:string}){
 const [open,setOpen]=useState(false);
 useEffect(()=>{
  if(!open)return;
  const close=(e:MouseEvent)=>{const target=e.target as HTMLElement;if(!target.closest('[data-custom-select]'))setOpen(false)};
  document.addEventListener('mousedown',close);
  return()=>document.removeEventListener('mousedown',close);
 },[open]);
 const selected=options.find(x=>x.value===value);
 return <div className="custom-select" data-custom-select>
  <button type="button" className="custom-select-trigger" onClick={()=>setOpen(v=>!v)} aria-expanded={open}>
   <span className="min-w-0 text-left"><span className={cls('block truncate font-semibold',selected?'text-white':'text-white/45')}>{selected?.label||placeholder}</span>{selected?.description&&<span className="mt-0.5 block truncate text-[11px] text-white/30">{selected.description}</span>}</span>
   <ChevronRight size={17} className={cls('shrink-0 text-white/35 transition-transform',open?'rotate-90':'rotate-0')}/>
  </button>
  <AnimatePresence>
   {open&&<motion.div initial={{opacity:0,y:-5,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-5,scale:.98}} className="custom-select-menu max-h-72 overflow-y-auto">
    {options.length ? options.map(o=><button type="button" key={o.value} onClick={()=>{onChange(o.value);setOpen(false)}} className={cls('custom-select-option',o.value===value?'custom-select-option-active':'')}>
     <span className="min-w-0 flex-1 text-left"><span className="block break-words font-semibold">{o.label}</span>{o.description&&<span className="mt-0.5 block break-words text-[11px] text-white/30">{o.description}</span>}</span>
     {o.value===value&&<CheckCircle2 size={16} className="shrink-0 text-violet-200"/>}
    </button>) : <div className="px-4 py-3 text-sm text-white/35">Нет доступных категорий</div>}
   </motion.div>}
  </AnimatePresence>
 </div>;
}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block"><div className="mb-1 text-xs font-semibold text-white/45">{label}</div>{children}</label>}
